   if(sheetName==='Semaines_Types'||sheetName==='Prix')continue;const ws=workbook.Sheets[sheetName],range=XLSX.utils.decode_range(ws['!ref']||'A1:A1'),limit=Math.min(range.e.r+1,maxRows);
