     const a=String(cell(ws,r,1)).trim();if(a==='FICHE RECETTE'||a==='FICHE DESSERT'){next=r;break}if(a==='INGRÉDIENTS PAR PERSONNE')ih=r;if(a==='ÉTAPES DE PRÉPARATION'){sh=r;break}if(a)meta[a]=cell(ws,r,2);
