UI.kiffSection=function(){const selected=App.week().kiffSelection||[],items=selected.map(n=>App.state.desserts.find(d=>d.n===n)).filter(Boolean);return `<article class="day fruit-day fruit-v43 kiff-v46"><div class="meal-line1"><b>🍰 P’tit kiff</b><span><button class="mini touch-mini" onclick="UI.kiffMenu()">⚙️</button></span></div><div class="fruit-meal-frame"><div class="fruit-names">${items.length?items.map(x=>esc(x.n)).join(' · '):'<span class="muted">Aucun dessert sélectionné</span>'}</div></div></article>`};
UI.kiffPicker=function(){const selected=App.week().kiffSelection||[];this.open(this.top()+`<h2>🍰 P’tit kiff</h2><div class="fruit-checks">${App.state.desserts.map(d=>`<label class="choice"><input type="checkbox" ${selected.includes(d.n)?'checked':''} onchange="UI.toggleKiff('${encodeURIComponent(d.n)}',this.checked)"> ${esc(d.n)}</label>`).join('')}</div>`)};
UI.toggleKiff=function(n,on){n=decodeURIComponent(n);let a=App.week().kiffSelection||[];if(on&&!a.includes(n))a.push(n);if(!on)a=a.filter(x=>x!==n);App.week().kiffSelection=a;Store.save();this.renderPlanning();this.renderCourses()};
const renderPlanningBase43=UI.renderPlanning.bind(UI);UI.renderPlanning=function(){renderPlanningBase43();planningGrid.insertAdjacentHTML('beforeend',this.fruitSection()+this.kiffSection())};
UI.aggregate=function(){const m={};for(let i=0;i<14;i++){const r=App.recipe(App.meal(i));if(!r)continue;const p=App.week().portions[i]??App.state.portion;for(const x of r.i){const k=x[0]+'|'+x[2];(m[k]??={a:x[0],q:0,u:x[2],g:x[3]}).q+=x[1]*p}}for(const f of App.fruitsForWeek()){const k=f.n+'|'+f.u;(m[k]??={a:f.n,q:0,u:f.u,g:'Fruits'}).q+=f.q}for(const n of (App.week().kiffSelection||[])){const d=App.state.desserts.find(x=>x.n===n);if(!d)continue;for(const x of d.i){const k=x[0]+'|'+x[2];(m[k]??={a:x[0],q:0,u:x[2],g:x[3]}).q+=x[1]}}return Object.values(m)};
UI.effectiveQty=function(x){const key=App.state.visible+'|'+x.a+'|'+x.u,manual=App.state.manualQty[key],base=Math.round(x.q*1000)/1000;if(manual&&manual.base===base)return manual.q;if(manual)delete App.state.manualQty[key];return base};
UI.renderCourses=function(){let groups={},total=0;for(const x of this.aggregate()){if(x.g==='Fruits & légumes')x.g='Légumes';const state=App.state.stock[x.a]||'missing';if(state==='sufficient')continue;x.calc=x.q*(state==='partial'?.5:1);x.buy=this.effectiveQty({...x,q:x.calc});const p=App.state.prices[x.a]||[0,x.u==='g'?'kg':x.u==='ml'?'L':x.u];x.cost=p[0]*((x.u==='g'||x.u==='ml')?x.buy/1000:x.buy);total+=x.cost;(groups[x.g]??=[]).push(x)}const manual=App.state.manual[App.state.visible]||[];manual.forEach((a,i)=>(groups['Ajouts manuels']??=[]).push({a,manual:i,cost:0}));const d=dateOf(App.state.visible);courseHero.innerHTML=`<div class="hero ${App.week().base.split(' ')[0]}"><p class="course-period">📅 Du ${d.toLocaleDateString('fr-FR')} au ${addDays(d,6).toLocaleDateString('fr-FR')}</p><h2>Total estimé : ${euro(total)}</h2><p>Les ajouts manuels sont exclus du total.</p></div>`;courseList.innerHTML=Object.entries(groups).map(([g,a])=>`<div class="shop ${g==='Ajouts manuels'?'manual':''}"><div class="shop-title"><h3>${g}</h3><p class="subtotal">${g==='Ajouts manuels'?'Non inclus':euro(a.reduce((z,x)=>z+x.cost,0))}</p></div>${a.map(x=>{const key=App.state.visible+'|'+g+'|'+x.a,p=App.state.prices[x.a]||[0,'unité'];return `<div class="shoprow shoprow-v43"><input type="checkbox" ${App.state.checks[key]?'checked':''} onchange="App.state.checks['${key.replaceAll("'","\\'")}']=this.checked;Store.save()"><div class="shop-one-line"><b>${esc(x.a)}${x.manual===undefined?' '+UI.qty(x.buy,x.u):''}</b></div><div class="shop-price">${x.manual===undefined?`${p[0].toFixed(2).replace('.',',')} €/${p[1]} <button class="pencil" onclick="UI.editQuantity('${encodeURIComponent(x.a)}','${encodeURIComponent(x.u)}',${x.calc})">✏️</button> <b>${euro(x.cost)}</b>`:`<button class="btn danger" onclick="UI.deleteManual(${x.manual})">×</button>`}</div></div>`}).join('')}</div>`).join('')};
UI.editQuantity=function(a,u,base){a=decodeURIComponent(a);u=decodeURIComponent(u);const key=App.state.visible+'|'+a+'|'+u,m=App.state.manualQty[key],value=m&&m.base===base?m.q:base,continuous=u==='g'||u==='ml';this.open(`<div class="modal-top"><button class="btn" onclick="UI.close()">Retour</button><button class="btn" onclick="UI.resetQuantity('${encodeURIComponent(a)}','${encodeURIComponent(u)}')">Reset la quantité</button></div><h2>${esc(a)}</h2>${continuous?`<input id="manualQtyValue" type="number" min="0" step="1" value="${value}" onchange="UI.saveQuantity('${encodeURIComponent(a)}','${encodeURIComponent(u)}',${base},+this.value)"> ${u}`:`<div class="row"><button class="btn" onclick="UI.stepQuantity('${encodeURIComponent(a)}','${encodeURIComponent(u)}',${base},-1)">−</button><b id="manualQtyValue">${value}</b><button class="btn" onclick="UI.stepQuantity('${encodeURIComponent(a)}','${encodeURIComponent(u)}',${base},1)">+</button></div>`}<br><br>`)};
UI.saveQuantity=function(a,u,base,q){a=decodeURIComponent(a);u=decodeURIComponent(u);if(q>=0)App.state.manualQty[App.state.visible+'|'+a+'|'+u]={base,q};Store.save();this.renderCourses()};
UI.stepQuantity=function(a,u,base,d){a=decodeURIComponent(a);u=decodeURIComponent(u);const key=App.state.visible+'|'+a+'|'+u,current=App.state.manualQty[key]?.q??base,q=Math.max(0,current+d);App.state.manualQty[key]={base,q};manualQtyValue.textContent=q;Store.save();this.renderCourses()};
UI.resetQuantity=function(a,u){a=decodeURIComponent(a);u=decodeURIComponent(u);delete App.state.manualQty[App.state.visible+'|'+a+'|'+u];Store.save();this.close();this.renderCourses()};
UI.openRecipe=function(n,p=2){const r=App.recipe(decodeURIComponent(n));this.current=r;this.open(this.top('UI.editRecipe()')+`<h2>${ICON[r.c]} ${App.displayRecipe(r)}</h2><p>⏱️ ${r.t} min · ${euro(App.cost(r,p))}</p><h3>Ingrédients pour ${p} personnes</h3><ul>${r.i.map(x=>`<li><b>${Math.round(x[1]*p*100)/100} ${x[2]}</b> de ${esc(x[0])}</li>`).join('')}</ul><h3>Procédure</h3><ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`)};

const renderPlanningV47=UI.renderPlanning.bind(UI);UI.renderPlanning=function(){renderPlanningV47();const d=dateOf(App.state.visible),b=App.weekBalance(),hero=planningHero.querySelector('.hero');if(!hero)return;const oldPortion=hero.querySelector('.default-portion');if(oldPortion)oldPortion.remove();const dateP=hero.querySelector('p');if(dateP){dateP.className='planning-date-row';dateP.innerHTML=`<span>📅 Du ${d.toLocaleDateString('fr-FR')} au ${addDays(d,6).toLocaleDateString('fr-FR')}</span><button class="btn portion-compact" onclick="UI.defaultPortion()">👥 ${App.state.portion}</button>`;dateP.insertAdjacentHTML('afterend',`<div class="week-balance"><span>🥕 ${b.Végétarien}</span><span>🥩 ${b.Viande}</span><span>🐟 ${b.Poisson}</span><span>🧀 ${b.Fromage}</span><span>🍎 ${b.Fruits}</span><span>🍰 ${b.Dessert}</span></div>`)} };
(async()=>{try{await loadExcelMaster();await App.init()}catch(e){console.error('Initialisation impossible',e);Store.status('⚠ Erreur de démarrage','error')}})();
